Matrix transpose( const Matrix& m )
{
    if( m.empty() )
    {
        return {};
    }
    Matrix out( m[0].size(), std::vector<double>( m.size(), 0.0 ) );
    for( std::size_t r = 0; r < m.size(); ++r )
    {
        for( std::size_t c = 0; c < m[r].size(); ++c )
        {
            out[c][r] = m[r][c];
        }
    }
    return out;
}

